{
  "command": "cd \"/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes/baseline/slot0\" && ls data/raw/legac_dr2/ 2>/dev/null | head -30; echo ---; grep -rniE \"wavelength (range|coverage)|6300|8800|observed.frame|rest.frame\" data/raw/legac_dr2/ --include=\"*.md\" --include=\"*.txt\" --include=\"*.html\" --include=\"*.rst\" 2>/dev/null | head -20",
  "description": "List LEGA-C DR2 docs and grep for wavelength range"
}

{
  "command": "cd "/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes/baseline/slot0" && cat data/raw/legac_dr2/README.md | head -60; echo ---PDF---; python3 -I -c "
import sys
try:
    from pypdf import PdfReader
except ImportError:
    from PyPDF2 import PdfReader
r = PdfReader('data/raw/legac_dr2/ESO_DR2_release_description.pdf')
txt = '\n'.join(p.extract_text() or '' for p in r.pages)
import re
for m in re.finditer(r'[^\n]*(?:wavelength|Å|Angstrom|resolution|R\s*[=~]\s*\d)[^\n]*', txt, re.I):
    print(m.group(0).strip())
" 2>&1 | head -40",
  "description": "Read LEGA-C README and grep the ESO DR2 PDF for wavelength statements"
}

{
  "command": "cd \"/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes/baseline/slot0\" && (pdftotext data/raw/legac_dr2/ESO_DR2_release_description.pdf - 2>/dev/null || .venv/bin/python -I -c \"\nimport fitz\nd=fitz.open('data/raw/legac_dr2/ESO_DR2_release_description.pdf'); print('\\n'.join(p.get_text() for p in d))\") | grep -niE \"wavelength|\u00c5|angstrom|resolution|R ?[=~\u2248] ?[0-9]|nm\\b|per pixel|dispersion\" | head -30",
  "description": "Extract wavelength and resolution statements from the ESO DR2 release PDF"
}

{
  "command": "cd "/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes/baseline/slot0" && f=$(ls data/raw/legac_dr2/sp/*.fits | head -1); .venv/bin/python -I -c "
import sys
from astropy.io import fits
h=fits.getheader(sys.argv[1],0); h1=fits.getheader(sys.argv[1],1)
for k in ('WAVELMIN','WAVELMAX','SPEC_RES','SPECSYS','Z'):
    print(k, h.get(k, h1.get(k)))
" "$f"",
  "description": "Print WAVELMIN/WAVELMAX from one LEGA-C spectrum header"
}
